 "mainEntity": [
  {
   "@type": "Question",
   "name": "Will heartworm preventives run out too?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "No. This news is about the treatment injection for dogs that are already infected. Monthly preventives and preventive injections are not affected."
   }
  },
  {
   "@type": "Question",
   "name": "When will it run out in Korea?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "There is no official announcement yet. The withdrawal outside the US has been discussed, and word in Korea is that it gets hard to find from next year. Ask your vet about stock and timing."
   }
  },
  {
   "@type": "Question",
   "name": "Can an infected dog still be treated without it?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Yes, but it is slower. Countries without melarsomine use a long course of an antibiotic plus a preventive. It takes much longer and the heart and lungs stay under strain, so decide with your vet."
   }
  },
  {
   "@type": "Question",
   "name": "Do dogs need prevention in winter too?",
   "acceptedAnswer": {
    "@type": "Answer",
    "text": "Many vets recommend year-round prevention, and it matters more as treatment gets harder. Set the plan for your area with your vet."
   }
  }
 ]
